function row=compute_joint_candidate_row_v1(sim,fit,cfg,method,rep,seed,r,g,alpha,runtime_seconds,primary_gate,sentinel_gate)
%COMPUTE_JOINT_CANDIDATE_ROW_V1 One point of the full (r,g,alpha) cube.
method=string(method);
if isfield(fit,'valid') && fit.valid
 st=compute_external_alpha_fit_stats_v1(sim.X,fit,method);
 truth=sim.labels(:); out=logical(sim.outlier(:)); intrue=~out; pred=fit.labels(:); trim=logical(fit.trim(:));
 ari=adjusted_rand_index_v1(truth(intrue),pred(intrue));
 tp=sum(trim&out); fp=sum(trim&~out); fn=sum(~trim&out);
 if any(out), pr=tp/max(tp+fp,1); re=tp/max(tp+fn,1); f1=2*pr*re/max(pr+re,eps); else, pr=NaN;re=NaN;f1=NaN;end
else
 st=empty_stats(); ari=NaN;pr=NaN;re=NaN;f1=NaN;
end
row=table(cfg.scenario_id,cfg.base_scenario_id,rep,seed,method,cfg.n,cfg.p,cfg.p_over_n,cfg.r0,cfg.c0,r,g, ...
 string(cfg.arm),string(cfg.difficulty),string(cfg.contamination),string(cfg.joint_role),cfg.alpha0,alpha, ...
 logical(primary_gate),logical(sentinel_gate),ari,pr,re,f1,st.W_raw,st.W_ratio,st.R2,st.explained,st.native_score, ...
 st.objective_per_keep,st.trim_rate,st.trim_gap_ratio,st.trim_gap_log10,st.trim_gap_robust, ...
 field_or(fit,'objective',NaN),logical(field_or(fit,'valid',false)),string(field_or(fit,'message',"")),runtime_seconds, ...
 string(field_or(fit,'selector',"")),field_or(fit,'N_starts',NaN),field_or(fit,'valid_starts',NaN), ...
 string(field_or(fit,'selected_init_family',"")),field_or(fit,'selected_objective_rank',NaN), ...
 field_or(fit,'selector_score',NaN),field_or(fit,'selector_cv_score',NaN),field_or(fit,'tauW',NaN),field_or(fit,'tauT',NaN), ...
 'VariableNames',{'scenario_id','base_scenario_id','replicate','seed','method','n','p','p_over_n','r0','g0','r','g', ...
 'arm','difficulty','contamination','joint_role','alpha0','alpha','primary_gate','sentinel_gate','ari_inlier', ...
 'trim_precision','trim_recall','trim_f1','W_raw','W_ratio','R2','explained','native_score','objective_per_keep', ...
 'trim_rate','trim_gap_ratio','trim_gap_log10','trim_gap_robust','objective','valid','message','runtime_seconds', ...
 'internal_selector','N_starts','valid_starts','selected_init_family','selected_objective_rank','selector_score', ...
 'selector_cv_score','tauW','tauT'});
end
function st=empty_stats()
st=struct('W_raw',NaN,'W_ratio',NaN,'R2',NaN,'explained',NaN,'native_score',NaN,'objective_per_keep',NaN, ...
 'trim_rate',NaN,'trim_gap_ratio',NaN,'trim_gap_log10',NaN,'trim_gap_robust',NaN);
end
function v=field_or(s,name,d)
if isfield(s,name)&&~isempty(s.(name)),v=s.(name);else,v=d;end
end
